if (new URLSearchParams(window.location.search).get("embed") === "1") document.documentElement.classList.add("embedded");

const firstTab=new URLSearchParams(window.location.search).get('view');
const state={view:['overview','shops','scanner','products','dna'].includes(firstTab)?firstTab:'overview',shop:'s1',product:'p1',dna:'shop',newShopStep:0,modal:false,search:'',platform:'all',productSearch:'',productCategory:'All products',scanState:'idle',progress:34,scanTimer:null,approval:false,shopDraft:{name:'',platform:'Etsy',url:'',country:'US',categories:['Hats & Caps'],mode:'discovery',cadence:'daily'},logs:[{t:'09:42:18',v:'Phát hiện listing mới · Listing #A104'}, {t:'09:41:56',v:'Ghi nhận ảnh gallery · 6/7 ảnh'}, {t:'09:41:30',v:'Kiểm tra dữ liệu trùng ASIN / listing ID'}, {t:'09:40:12',v:'Đã xác minh shop URL và category'}]};
const shops=[{id:'s1',name:'COUPLEHOODIES',platform:'Amazon',category:'Apparel & Gifts',total:42,analyzed:36,profile:86,status:'Profile ready',avatar:'CH',accent:'#e8edff'},{id:'s2',name:'EMBROLY',platform:'Amazon',category:'Embroidery',total:36,analyzed:24,profile:68,status:'Analyzing',avatar:'EM',accent:'#f7e8dc'},{id:'s3',name:'BruceEmbroideryStore',platform:'Etsy',category:'Hats & Caps',total:48,analyzed:41,profile:91,status:'Profile ready',avatar:'BE',accent:'#e3f2ed'},{id:'s4',name:'BrightShineCrochet',platform:'Etsy',category:'Crochet',total:31,analyzed:18,profile:48,status:'Discovery',avatar:'BC',accent:'#f5e9f3'}];
const products=[{id:'p1',shop:'s1',name:'Everyday Embroidered Cap',cat:'Hats & Caps',color:'brown',tone:'#b29270',text:'EVERYDAY',roles:['Hero','Detail','Lifestyle','Variation'],confidence:96},{id:'p2',shop:'s1',name:'Minimal Custom Embroidery Tee',cat:'Apparel',color:'blue',tone:'#91acd1',text:'CUSTOM',roles:['Hero','Detail','Size Chart','Lifestyle'],confidence:90},{id:'p3',shop:'s1',name:'Personalized Gift Tote Bag',cat:'Accessories',color:'green',tone:'#91af92',text:'MY STORY',roles:['Hero','Lifestyle','Detail','Gift'],confidence:84},{id:'p4',shop:'s1',name:'Retro Washed Cotton Cap',cat:'Hats & Caps',color:'pink',tone:'#c995a5',text:'SUN DAY',roles:['Hero','UGC','Detail'],confidence:94},{id:'p5',shop:'s1',name:'Organic Canvas Everyday Tote',cat:'Accessories',color:'brown',tone:'#ac8d79',text:'GOOD DAY',roles:['Hero','Variation','Lifestyle'],confidence:87},{id:'p6',shop:'s1',name:'Weekend Gift Embroidered Hat',cat:'Hats & Caps',color:'green',tone:'#78957c',text:'WEEKEND',roles:['Hero','Detail','Variation','UGC'],confidence:93},{id:'p7',shop:'s2',name:'Monogram Embroidered Cap',cat:'Hats & Caps',color:'brown',tone:'#ab9784',text:'INITIAL',roles:['Hero','Detail','Variation'],confidence:89},{id:'p8',shop:'s2',name:'Custom Stitch Tee',cat:'Apparel',color:'blue',tone:'#7f9aba',text:'PERSONAL',roles:['Hero','Detail'],confidence:87},{id:'p9',shop:'s3',name:'Everyday Personalized Hat',cat:'Hats & Caps',color:'pink',tone:'#ae8694',text:'YOUR NAME',roles:['Hero','Detail','Lifestyle','UGC'],confidence:94},{id:'p10',shop:'s4',name:'Handmade Canvas Tote',cat:'Accessories',color:'green',tone:'#94b59a',text:'HANDMADE',roles:['Hero','Lifestyle','Gift'],confidence:90}];
const profileTabs=[['shop','Shop DNA'],['category','Category Style'],['listing','Listing Visual'],['image','Image Style'],['platform','Platform'],['campaign','Seasonal/Campaign']];
const traitSets={shop:[['Minimalism',82,'Clean shapes and uncluttered styling'],['Warm & Friendly',77,'Inviting, accessible atmosphere'],['Craft Authenticity',91,'Embroidery, texture and tactile detail'],['Premium Positioning',62,'Balanced premium–everyday'],['Lifestyle Emphasis',74,'Human context over pure studio'],['Visual Consistency',87,'Stable presentation across listings']],category:[['Embroidery Close-up',96,'Thread texture is prominent'],['Neutral Backdrop',82,'Plain, warm neutrals'],['Colorway Consistency',91,'Same lighting for every variant'],['Product Accuracy',98,'Exact form and artwork']],listing:[['Hero First',98,'Clean front-facing product'],['Detail Coverage',88,'Embroidery and fabric macros'],['Lifestyle / UGC',72,'Everyday scenes'],['Variation Clarity',87,'Color options are recognizable']],image:[['Natural Light',83,'Soft diffuse lighting'],['Realistic Fabric',97,'Tactile stitching'],['Shallow Depth of Field',64,'Moderate subject separation'],['Human Presence',69,'Casual everyday models']],platform:[['Listing Coverage',95,'Platform-specific gallery roles'],['Copy Consistency',85,'Tone across descriptions'],['Thumbnail Legibility',93,'Product clearly readable'],['Compliance Readiness',76,'Needs human policy review']],campaign:[['Evergreen Core',92,'Default neutral DNA'],['Gift Season Layer',68,'Seasonal props'],['Holiday Variants',57,'Holiday palette overlays'],['Campaign Isolation',95,'Never overwrite core DNA']]};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500)}
function selectedShop(){return shops.find(s=>s.id===state.shop)||shops[0]}
function pillStatus(s){return s==='Profile ready'?'<span class="pill good"><span class="dot"></span>Profile ready</span>':s==='Analyzing'?'<span class="pill blue"><span class="dot"></span>Analyzing</span>':'<span class="pill wait"><span class="dot"></span>Discovery</span>'}
function metrics(){const discovered=shops.reduce((a,b)=>a+b.total,0),analyzed=shops.reduce((a,b)=>a+b.analyzed,0);return `<div class="metrics"><div class="metric"><div class="metric-ico">▤</div><div><div class="metric-label">Shop library</div><div class="metric-num">${shops.length}</div><div class="metric-note">Amazon · Etsy</div></div></div><div class="metric"><div class="metric-ico">▦</div><div><div class="metric-label">Products discovered</div><div class="metric-num">${discovered}</div><div class="metric-note">Demo listings</div></div></div><div class="metric"><div class="metric-ico">◉</div><div><div class="metric-label">AI analyzed</div><div class="metric-num">${analyzed}</div><div class="metric-note">${Math.round(analyzed/discovered*100)}% coverage</div></div></div><div class="metric"><div class="metric-ico">✺</div><div><div class="metric-label">Profiles ready</div><div class="metric-num">${shops.filter(s=>s.profile>=80).length}</div><div class="metric-note">Versioned snapshots</div></div></div></div>`}
function shopCard(s){return `<button class="shop-card ${s.id===state.shop?'selected':''}" data-select-shop="${s.id}"><div class="shop-top"><div class="shop-avatar" style="background:${s.accent}">${esc(s.avatar)}</div><div style="min-width:0;flex:1"><div class="shop-name">${esc(s.name)}</div><div class="shop-meta">${esc(s.platform)} · ${esc(s.category)}</div></div>${pillStatus(s.status)}</div><div class="shop-stats"><div><b>${s.total}</b><span>Discovered</span></div><div><b>${s.analyzed}</b><span>Analyzed</span></div><div><b>${s.profile}%</b><span>Coverage</span></div></div><div class="profile-track"><div class="profile-progress" style="width:${s.profile}%"></div></div><div class="shop-footer"><span class="subtle">${esc(s.name)} · DNA v0.3</span><span style="font-size:10px;font-weight:800;color:#5578cb">Open →</span></div></button>`}
function overview(){return `${metrics()}<div class="grid2"><section class="card"><div class="card-head"><h2>Shop Library</h2><button class="btn tiny" data-view="shops">View all shops →</button></div><div class="card-body"><div class="shops-grid">${shops.map(shopCard).join('')}</div></div></section><section class="card"><div class="card-head"><h2>Brand Intelligence</h2><span class="pill blue">Evidence based</span></div><div class="card-body"><div class="flowsteps">${[['01','Discover storefront','Browse category and listing pagination'],['02','Capture listing gallery','Collect image roles, titles and product attributes'],['03','Gemini visual intelligence','Evaluate photography, layout and product detail'],['04','Synthesize Shop DNA','Aggregate consistent patterns and exceptions'],['05','Review & apply','Approve a version before using in production']].map(a=>`<div class="flowstep"><span class="step-ico">${a[0]}</span><div><strong>${a[1]}</strong><p>${a[2]}</p></div></div>`).join('')}</div><div class="callout" style="margin-top:14px">Mỗi kết luận cần có <b>listing/image evidence</b>, tỷ lệ xuất hiện, confidence và ngoại lệ. Không dùng dữ liệu mô phỏng này để ra quyết định sản xuất.</div></div></section></div><div class="overview-bottom"><section class="card"><div class="card-head"><h2>Analysis activity</h2><span class="subtle">Example coverage per shop</span></div><div class="card-body"><div class="small-chart">${[36,52,44,75,82,63,91,68,80,72,90,64].map(v=>`<div class="bar" style="height:${v}%"></div>`).join('')}</div><p class="hint" style="margin-top:11px">Demo chart · Không phải dữ liệu của shop thực tế.</p></div></section><section class="card"><div class="card-head"><h2>Connected platforms</h2></div><div class="card-body">${[['Amazon',2],['Etsy',2],['Shopify',0]].map(a=>`<div class="platform-row"><span>${a[0]}</span><strong>${a[1]} shops</strong></div>`).join('')}<button class="btn light" style="margin-top:10px;width:100%" data-action="add-shop">＋ Add another platform shop</button></div></section></div>`}
function shopLibrary(){const list=shops.filter(s=>(state.platform==='all'||s.platform===state.platform)&&s.name.toLowerCase().includes(state.search.toLowerCase()));return `${metrics()}<div class="view-tools"><label class="search-wrap">⌕ <input id="shop-search" value="${esc(state.search)}" placeholder="Search shop name or brand..." autocomplete="off"></label><select id="platform-filter" class="form-select"><option value="all" ${state.platform==='all'?'selected':''}>All platforms</option><option ${state.platform==='Amazon'?'selected':''}>Amazon</option><option ${state.platform==='Etsy'?'selected':''}>Etsy</option><option ${state.platform==='Shopify'?'selected':''}>Shopify</option></select><button class="btn" data-action="refresh-demo">⟳ Refresh</button></div><div class="card"><div class="card-head"><h2>All managed shops <span class="pill">${list.length}</span></h2><button class="btn tiny primary" data-action="add-shop">＋ New Shop</button></div><div class="scrollx"><table class="shop-table"><thead><tr><th>Shop / platform</th><th>Category</th><th>Discovered</th><th>Analyzed</th><th>Brand DNA</th><th>Status</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><span class="rowname">${esc(s.name)}</span><br><span style="font-size:9px">${esc(s.platform)}</span></td><td>${esc(s.category)}</td><td>${s.total}</td><td>${s.analyzed}</td><td><div style="width:110px" class="profile-track"><div class="profile-progress" style="width:${s.profile}%"></div></div><span class="subtle">${s.profile}% coverage</span></td><td>${pillStatus(s.status)}</td><td><button class="btn tiny" data-shop-open="${s.id}">Open →</button></td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">Không có shop phù hợp. Hãy thử bộ lọc khác.</div>':''}</div>`}
function scanStages(){let idx=state.progress<25?0:state.progress<50?1:state.progress<80?2:3;let names=['Discover storefront','Capture listings','Analyze images','Synthesize DNA'];return `<div class="scanner-stage">${names.map((n,i)=>`<div class="stage ${i<idx?'done':i===idx?'on':''}"><div class="stage-num">STEP 0${i+1} ${i<idx?'✓':i===idx?'· ACTIVE':''}</div><div class="stage-name">${n}</div><small>${['Shop tree & pagination','Gallery & product attributes','Gemini + evidence','Confidence & exceptions'][i]}</small></div>`).join('')}</div>`}
function scanner(){const s=selectedShop();return `<div class="view-tools"><label class="search-wrap" style="max-width:380px">◈ <span class="subtle" style="white-space:nowrap">Active shop</span><select id="scan-shop" style="border:0;background:transparent;outline:none;width:100%;min-width:0;font-weight:800;color:#35547c">${shops.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(x.name)} · ${x.platform}</option>`).join('')}</select></label><span class="pill ${state.scanState==='running'?'good':state.scanState==='paused'?'wait':'blue'}">● ${state.scanState==='idle'?'Ready for demo':state.scanState==='running'?'Demo scanning':state.scanState==='paused'?'Demo paused':'Demo completed'}</span><span class="subtle">All browser actions are simulated in this prototype.</span></div><div class="scanner-layout"><section class="card"><div class="card-head"><div><h2>Browser Scanner</h2><div class="hint">${esc(s.name)} · ${esc(s.platform)} storefront</div></div><span class="pill blue">Controlled browser agent</span></div><div class="card-body"><div class="split-header"><div><strong style="font-size:12px;color:#3b5579">Storefront deep scan</strong><p class="hint">Crawl public product listings one at a time, deduplicate, record evidence and retry safely.</p></div><span class="pill">Demo session 001</span></div>${scanStages()}<div class="progress-inline"><span>Demo scan progress</span><span>${state.progress}% · ${Math.floor(state.progress*.42)}/42 sample products</span></div><div class="progress-wrap"><div class="progress-fill" style="width:${state.progress}%"></div></div><div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:15px"><button class="btn primary" data-action="scan-toggle">${state.scanState==='running'?'Ⅱ Pause demo':state.scanState==='paused'?'▷ Resume demo':'▷ Start demo scan'}</button><button class="btn" data-action="scan-retry">↻ Retry sample</button><button class="btn" data-action="scan-diff">↗ Incremental rescan</button><button class="btn danger" data-action="scan-stop">✕ Stop</button></div><div class="divider"></div><div class="split-header" style="margin-bottom:9px"><h3>Live session log (simulation)</h3><span class="subtle">Evidence · checkpoints · retries</span></div><div class="log-list">${state.logs.slice(0,8).map(l=>`<div class="log-entry"><span class="log-time">${l.t}</span><span class="log-text">${esc(l.v)}</span></div>`).join('')}</div></div></section><aside class="card scanner-right"><div class="card-head"><h2>Scan configuration</h2><span class="pill">Per shop</span></div><div class="card-body"><div class="kv"><span>Platform</span><b>${esc(s.platform)}</b></div><div class="kv"><span>Discovered</span><b>${s.total} products</b></div><div class="kv"><span>Processing</span><b>1 at a time</b></div><div class="kv"><span>Queue priority</span><b>Low · shared Gemini</b></div><div class="kv"><span>Deduplication</span><b>Listing ID + image hash</b></div><div class="kv"><span>Retry policy</span><b>Backoff · 3 attempts</b></div><div class="kv"><span>Auth boundary</span><b>Public / authorized only</b></div><div class="subheading">Browser checkpoints</div><div class="callout">Danh mục → từng trang listing → ảnh gallery → dữ liệu sản phẩm → Gemini → cập nhật Profile nháp. Tiếp tục từ checkpoint khi người dùng Pause/Resume.</div><div class="callout amber" style="margin-top:10px">CAPTCHA, HTTP 403, đăng nhập bắt buộc hoặc giới hạn nền tảng → <b>Needs attention</b>. Không tự vượt bảo vệ hoặc tự đoán dữ liệu bị thiếu.</div><div style="margin-top:12px"><button class="btn" style="width:100%" data-view="products">View discovered products →</button></div></div></aside></div>`}
function art(p,large=false){const isTee=p.cat==='Apparel',isTote=p.cat==='Accessories';const shape=isTee?`<path d="M71 37 100 25 125 28 142 25 172 37 190 72 164 84 153 67 153 154 89 154 89 67 78 84 52 72Z" fill="${p.tone}" stroke="#607087" stroke-width="2"/><path d="M100 25 Q122 55 142 25" fill="none" stroke="#627894" stroke-width="2"/>`:isTote?`<path d="M75 49 H172 L181 152 H64Z" fill="${p.tone}" stroke="#718096" stroke-width="2"/><path d="M93 54 V40 C93 6 153 6 153 40 V54" stroke="${p.tone}" stroke-width="12" fill="none"/><path d="M93 54 V40 C93 6 153 6 153 40 V54" stroke="#647785" stroke-width="1.5" fill="none"/>`:`<path d="M61 97 Q62 31 123 28 Q185 34 186 98 L186 114 L61 114Z" fill="${p.tone}" stroke="#6e7885" stroke-width="2"/><path d="M62 104 Q22 111 17 128 Q56 147 114 122" fill="${p.tone}" stroke="#718398" stroke-width="2"/><path d="M123 29 Q108 63 110 111" fill="none" stroke="#7e8793" stroke-width="1.5" stroke-dasharray="3 3"/><path d="M64 103 Q123 93 185 104" fill="none" stroke="#788795" stroke-width="2"/>`;return `<div class="product-art ${p.color} ${large?'art-large':''}"><div class="photo-shadow"></div><svg viewBox="0 0 240 180" role="img" aria-label="Illustrative ${esc(p.cat)} product artwork"><ellipse cx="120" cy="159" rx="62" ry="9" fill="#8b9aaa" opacity=".16"/>${shape}<text x="123" y="${isTee?96:isTote?110:83}" font-size="${isTee?10:isTote?10:9}" text-anchor="middle" fill="#f8f5ee" font-family="system-ui" font-weight="900" letter-spacing="1.1">${esc(p.text)}</text></svg></div>`}
function productCard(p){return `<button class="product-card ${p.id===state.product?'selected':''}" data-product="${p.id}">${art(p)}<div class="product-title">${esc(p.name)}</div><div class="product-ref">Listing ID · DEMO-${esc(p.id.toUpperCase())}</div><div class="product-card-bottom"><span class="pill blue">${p.roles.length} roles</span><small>${p.confidence}% AI</small></div></button>`}
function productExplorer(){const s=selectedShop();const shopProducts=products.filter(p=>p.shop===s.id);const filtered=shopProducts.filter(p=>(state.productCategory==='All products'||p.cat===state.productCategory)&&p.name.toLowerCase().includes(state.productSearch.toLowerCase()));const p=shopProducts.find(p=>p.id===state.product)||shopProducts[0];return `<div class="view-tools"><label class="search-wrap">⌕ <input id="product-search" value="${esc(state.productSearch)}" placeholder="Search products, product ID, keyword..." autocomplete="off"></label><select id="product-shop" class="form-select">${shops.map(x=>`<option value="${x.id}" ${s.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="btn" data-action="grid-view">▦ Grid</button><span class="pill">Illustrative listings</span></div><div class="product-layout"><div class="filter-tree"><div class="tree-name">▥ Product tree</div>${['All products','Hats & Caps','Apparel','Accessories'].map((n,i)=>`<div class="tree-line ${state.productCategory===n?'active':''}" data-category="${esc(n)}"><span>${['▣','⚑','▱','▰'][i]} &nbsp;${esc(n)}</span><span class="tree-num">${i===0?shopProducts.length:shopProducts.filter(x=>x.cat===n).length}</span></div>`).join('')}<p class="hint" style="margin:12px 6px 2px">Filter theo category và lưu context khi chuyển giữa các sản phẩm.</p></div><section class="card"><div class="card-head"><div><h2>Product Explorer <span class="pill">${filtered.length}</span></h2><p class="hint">Gallery capture · listing role · visual evidence</p></div><span class="pill blue">Grid</span></div><div class="card-body" style="padding:10px"><div class="product-gallery">${filtered.map(productCard).join('')||'<div class="empty">Không có sản phẩm phù hợp hoặc chưa có bằng chứng được thu thập.</div>'}</div></div></section><aside class="card inspector"><div class="card-head"><h2>Product Inspector</h2><span class="pill ${p?'good':'wait'}">${p?'AI parsed':'No evidence'}</span></div>${p?`${art(p,true)}<div class="inspector-body"><div class="detail-title">${esc(p.name)}</div><p class="detail-p">Illustrative listing · Demo ID ${p.id.toUpperCase()}<br>Category: ${p.cat} · Platform: ${s.platform}</p><div class="subheading">Gallery roles</div><div class="role-chips">${p.roles.map(x=>`<span class="role">${x}</span>`).join('')}</div><div class="subheading">Visual feature summary</div><div class="quality"><span>Product recognition</span><b>${p.confidence}%</b></div><div class="quality"><span>Fabric/material detail</span><b>High evidence</b></div><div class="quality"><span>Listing completeness</span><b>${p.roles.length} roles</b></div><div class="quality"><span>Source confidence</span><b>Illustrative only</b></div><div style="display:grid;gap:7px;margin-top:15px"><button class="btn primary" data-view="dna">Inspect Brand DNA →</button><button class="btn" data-action="flag-product">⚑ Flag questionable evidence</button></div></div>`:'<div class="empty">Shop chưa có sản phẩm trong prototype.</div>'}</aside></div>`}
function brandDNA(){const s=selectedShop(),ts=traitSets[state.dna];return `<div class="view-tools"><span class="pill blue">Current shop</span><select id="dna-shop" class="form-select">${shops.map(x=>`<option value="${x.id}" ${s.id===x.id?'selected':''}>${esc(x.name)} · ${x.platform}</option>`).join('')}</select><span class="pill ${state.approval?'good':'wait'}">${state.approval?'Approved v0.3':'Draft v0.3 · Review required'}</span><span class="subtle">Profile snapshots are versioned</span></div><div class="dna-layout"><aside class="card"><div class="card-head"><h2>Profile Layers</h2></div><nav class="profile-nav" aria-label="Brand profile layers">${profileTabs.map(([k,n],i)=>`<button class="${state.dna===k?'active':''}" data-dna="${k}">0${i+1} &nbsp;${n}</button>`).join('')}</nav><div style="padding:0 13px 13px"><div class="callout">Một shared workflow, nhưng <b>Shop DNA độc lập</b>. Không ghi đè Profile đã duyệt.</div></div></aside><section class="card"><div class="card-head"><div><h2>${profileTabs.find(x=>x[0]===state.dna)[1]}</h2><p class="hint">${esc(s.name)} · Observation-based interpretation</p></div><span class="pill blue">Confidence 88%</span></div><div class="card-body"><div class="profile-top"><div><div style="font-size:11px;font-weight:800;color:#3e597a">Visual personality fingerprint</div><div class="hint">Aggregated across sample listings, not a single prompt.</div></div><button class="btn tiny" data-action="explain-method">ⓘ Methodology</button></div><div class="trait-grid">${ts.map(([name,value,help])=>`<div class="trait"><div class="trait-name">${name}</div><div class="trait-help">${help}</div><div class="trait-track"><div class="trait-fill" style="width:${value}%"></div></div><div class="trait-value">${value}%</div></div>`).join('')}</div><div class="subheading">Dominant palette</div><div class="palette">${['#f2ede5','#d9c4aa','#8f7862','#4c675f','#ede5db','#2e4153'].map(x=>`<span class="swatch" style="background:${x}" title="${x}"></span>`).join('')}</div><p class="profile-paragraph">${state.dna==='shop'?'Mô tả minh họa: hình ảnh ấm áp, gần gũi, tối giản vừa phải; nhấn mạnh chất liệu và cảm giác thủ công. Những kết luận thực tế phải được chứng minh qua nhiều listing cùng các trường hợp ngoại lệ.':`Đây là lớp ${profileTabs.find(x=>x[0]===state.dna)[1]} trong Brand DNA. Các chỉ số minh họa cách AI tổng hợp xu hướng, tách riêng bằng chứng, mức độ tin cậy và ngoại lệ.`}</p><div class="callout">Output contract: <b>Observation → Frequency → Confidence → Evidence → Exceptions → Recommended constraints</b>. Những yếu tố chỉ quan sát ở một ảnh không trở thành luật toàn shop.</div></div></section><aside class="card evidence-panel"><div class="card-head"><h2>Evidence & Versions</h2><span class="pill">Auditable</span></div><div class="card-body"><div class="quality"><span>Listings reviewed</span><b>36 / 42</b></div><div class="quality"><span>Image evidence</span><b>218 items</b></div><div class="quality"><span>Exceptions flagged</span><b>7 cases</b></div><div class="quality"><span>Conflicts for review</span><b>2</b></div><div class="subheading">Representative observations</div><div class="evidence"><div class="evidence-item"><div class="ev-thumb">⚑</div><div><b>Fabric & embroidery detail</b><p>Observed in 28/36 demo listings · Confidence 92%</p></div></div><div class="evidence-item"><div class="ev-thumb">☀</div><div><b>Warm neutral lighting</b><p>Observed in 24/36 demo listings · Confidence 88%</p></div></div><div class="evidence-item"><div class="ev-thumb">▱</div><div><b>Hero + lifestyle pairing</b><p>Observed in 19/36 demo listings · Confidence 74%</p></div></div></div><div class="subheading">Profile versions</div><div class="version-list"><div class="version-row"><span><b>v0.3</b> · Current draft</span><span class="pill ${state.approval?'good':'wait'}">${state.approval?'Approved':'Pending'}</span></div><div class="version-row"><span><b>v0.2</b> · Archived</span><span class="subtle">2026-10-12</span></div></div><div style="display:grid;gap:7px;margin-top:14px"><button class="btn primary" data-action="approve-profile">✓ ${state.approval?'Approved (demo)':'Approve profile (demo)'}</button><button class="btn" data-action="export-profile">⇩ Export JSON profile</button><button class="btn" data-action="apply-profile">↗ Apply to workflow</button></div></div></aside></div>`}
function render(){document.querySelectorAll('.tab').forEach(b=>{const yes=b.dataset.view===state.view;b.classList.toggle('active',yes);b.setAttribute('aria-selected',String(yes))});document.getElementById('content').innerHTML=({overview,shops:shopLibrary,scanner,products:productExplorer,dna:brandDNA})[state.view]();document.title='CAM — Branding DNA · '+state.view}
function navigate(view){state.view=view;render();window.scrollTo({top:0,behavior:'smooth'})}
function time(){return new Date().toLocaleTimeString('en-US',{hour12:false})}
function scanInterval(){clearInterval(state.scanTimer);state.scanTimer=setInterval(()=>{if(state.scanState!=='running')return;state.progress=Math.min(100,state.progress+Math.ceil(Math.random()*4));if(state.progress%10<4)state.logs.unshift({t:time(),v:`Demo listing processed · ${Math.floor(state.progress*.42)}/42 · source evidence checkpoint`});if(state.progress>=100){state.scanState='done';clearInterval(state.scanTimer);state.logs.unshift({t:time(),v:'Demo scan complete. Draft synthesis ready.'})}if(state.view==='scanner')render()},650)}
function toggleScan(){if(state.scanState==='running'){state.scanState='paused';clearInterval(state.scanTimer);state.logs.unshift({t:time(),v:'Scan paused at latest product checkpoint.'})}else{if(state.scanState==='done')state.progress=0;state.scanState='running';state.logs.unshift({t:time(),v:'Resumed browser scan simulation (no network requests).'});scanInterval()}render()}
function exportProfile(){const s=selectedShop();const d={prototype:true,shop:{name:s.name,platform:s.platform},version:'0.3-draft',approved:state.approval,profile:Object.fromEntries(profileTabs.map(([k])=>[k,traitSets[k].map(([trait,score,definition])=>({trait,score,definition}))])),evidence_note:'All values are mock data, not researched brand findings'};const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cam-branding-dna-demo.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Đã xuất JSON mẫu. Không chứa dữ liệu thu thập thật.')}
function openModal(){state.modal=true;state.newShopStep=0;renderModal()}
function closeModal(){state.modal=false;document.getElementById('modal-root').innerHTML=''}
function renderModal(err=''){if(!state.modal)return;const d=state.shopDraft,step=state.newShopStep;document.getElementById('modal-root').innerHTML=`<div class="modal-overlay" id="overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="Add Shop"><div class="modal-head"><div><div class="eyebrow">Shop setup · Step ${step+1} / 3</div><h2 style="font-size:18px">${['Connect your shop','Select research scope','Review & create'][step]}</h2></div><button class="btn icon-only" data-action="modal-close" aria-label="Close Add Shop">✕</button></div><div class="modal-main"><div class="wizard">${[0,1,2].map(i=>`<span class="seg ${i<=step?'active':''}"></span>`).join('')}</div>${step===0?`<div class="field-grid"><div class="field"><label for="new-name">Shop name <span class="required">*</span></label><input id="new-name" maxlength="90" value="${esc(d.name)}" placeholder="Ví dụ: My Embroidery Store"></div><div class="field"><label for="new-platform">Platform <span class="required">*</span></label><select id="new-platform">${['Amazon','Etsy','Shopify'].map(x=>`<option ${x===d.platform?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span2"><label for="new-url">Storefront URL <span class="required">*</span></label><input type="url" id="new-url" value="${esc(d.url)}" placeholder="https://www.etsy.com/shop/your-shop"></div><div class="field"><label for="new-country">Marketplace / region</label><select id="new-country"><option value="US" ${d.country==='US'?'selected':''}>United States</option><option value="UK" ${d.country==='UK'?'selected':''}>United Kingdom</option><option value="DE" ${d.country==='DE'?'selected':''}>Germany</option></select></div><div class="field"><label>Connection mode</label><div class="callout">Public storefront · Không yêu cầu mật khẩu trong form này</div></div></div><div class="callout amber" style="margin-top:12px">Nếu cần đăng nhập, xác thực sẽ thực hiện trong phiên trình duyệt được cấp quyền. Không thu thập password hoặc vượt CAPTCHA.</div>`:step===1?`<div class="field-grid"><div class="field span2"><label>Product categories</label><div class="checks">${['Hats & Caps','Apparel','Accessories','Home & Gifts','Crochet'].map(x=>`<label class="check-chip"><input type="checkbox" data-category-check="${x}" ${d.categories.includes(x)?'checked':''}>${x}</label>`).join('')}</div></div><div class="field"><label for="new-mode">Initial scan</label><select id="new-mode"><option value="discovery" ${d.mode==='discovery'?'selected':''}>Discovery pilot · first 20 listings</option><option value="full" ${d.mode==='full'?'selected':''}>Full shop scan · all accessible listings</option></select></div><div class="field"><label for="new-cadence">Incremental refresh</label><select id="new-cadence"><option value="daily" ${d.cadence==='daily'?'selected':''}>Daily · changed listings only</option><option value="weekly" ${d.cadence==='weekly'?'selected':''}>Weekly</option><option value="manual" ${d.cadence==='manual'?'selected':''}>Manual only</option></select></div></div><div class="callout" style="margin-top:13px">Scanner sẽ lưu listing ID, gallery roles, source evidence, scan checkpoint và thời gian thay đổi để không phải quét lại mọi ảnh.</div>`:`<div class="field-grid"><div class="field span2"><label>Shop identification</label><div class="callout"><strong>${esc(d.name||'Unnamed shop')}</strong> · ${esc(d.platform)}<br>${esc(d.url||'No storefront URL')}<br>Region ${esc(d.country)}</div></div><div class="field span2"><label>Scan settings</label><div class="callout">${esc(d.categories.join(', '))}<br>${d.mode==='full'?'Full scan':'Pilot · 20 listings'} · ${esc(d.cadence)} refresh</div></div><div class="field span2"><label>Security / QA</label><div class="callout amber">URL allowlist, tenant separation, robots/ToS compliance, backoff, manual intervention for CAPTCHA, audit log and human-reviewed Profile approval.</div></div></div>`}${err?`<div class="modal-error">${esc(err)}</div>`:''}</div><div class="modal-footer"><button class="btn" data-action="${step===0?'modal-close':'modal-back'}">${step===0?'Cancel':'← Back'}</button><span class="subtle">Browser workers are not connected in this prototype.</span><button class="btn primary" data-action="${step===2?'modal-save':'modal-next'}">${step===2?'Create demo shop':'Continue →'}</button></div></section></div>`}
function readDraft(){for(let [key,id] of [['name','new-name'],['platform','new-platform'],['url','new-url'],['country','new-country'],['mode','new-mode'],['cadence','new-cadence']]){const el=document.getElementById(id);if(el)state.shopDraft[key]=el.value.trim()}const checks=document.querySelectorAll('[data-category-check]');if(checks.length)state.shopDraft.categories=[...checks].filter(x=>x.checked).map(x=>x.dataset.categoryCheck)}
function validShopURL(u,p){try{const x=new URL(u);if(x.protocol!=='https:'||x.username||x.password)return false;const h=x.hostname.toLowerCase();return p==='Amazon'?(h==='amazon.com'||h.endsWith('.amazon.com')||h.endsWith('.amazon.co.uk')||h.endsWith('.amazon.de')):p==='Etsy'?h==='etsy.com'||h==='www.etsy.com':/^[a-z0-9-]+\.myshopify\.com$/.test(h)}catch{return false}}
function nextWizard(){readDraft();const d=state.shopDraft;if(state.newShopStep===0){if(d.name.length<2){renderModal('Vui lòng nhập tên shop ít nhất 2 ký tự.');return}if(!validShopURL(d.url,d.platform)){renderModal('URL storefront chưa hợp lệ với nền tảng đã chọn. Yêu cầu HTTPS và domain chính thức.');return}}if(state.newShopStep===1&&!d.categories.length){renderModal('Chọn ít nhất một danh mục.');return}state.newShopStep++;renderModal()}
function saveShop(){readDraft();const d=state.shopDraft;const id='s'+(shops.length+1);shops.push({id,name:d.name,platform:d.platform,category:d.categories[0],total:0,analyzed:0,profile:0,status:'Discovery',avatar:d.name.slice(0,2).toUpperCase(),accent:'#e9f2ff'});state.shop=id;state.shopDraft={name:'',platform:'Etsy',url:'',country:'US',categories:['Hats & Caps'],mode:'discovery',cadence:'daily'};closeModal();navigate('shops');toast('Đã thêm shop vào dữ liệu mô phỏng. Không có tác vụ quét thật được tạo.')}
document.addEventListener('click',e=>{const el=e.target.closest('[data-view],[data-action],[data-select-shop],[data-shop-open],[data-product],[data-category],[data-dna],[data-nav]');if(!el)return;if(el.dataset.view){navigate(el.dataset.view);return}if(el.dataset.selectShop){state.shop=el.dataset.selectShop;navigate('dna');return}if(el.dataset.shopOpen){state.shop=el.dataset.shopOpen;navigate('scanner');return}if(el.dataset.product){state.product=el.dataset.product;render();return}if(el.dataset.category){state.productCategory=el.dataset.category;render();return}if(el.dataset.dna){state.dna=el.dataset.dna;render();return}if(el.dataset.nav){if(el.dataset.nav==='brand')navigate('overview');else toast('Đây là prototype Branding DNA. Các module CAM khác chỉ để minh họa navbar.');return}const action=el.dataset.action;if(action==='add-shop')openModal();if(action==='modal-close')closeModal();if(action==='modal-back'){readDraft();state.newShopStep--;renderModal()}if(action==='modal-next')nextWizard();if(action==='modal-save')saveShop();if(action==='export-profile')exportProfile();if(action==='refresh-demo')toast('Dữ liệu mô phỏng — không có backend để refresh.');if(action==='scan-toggle')toggleScan();if(action==='scan-retry'){state.logs.unshift({t:time(),v:'Retry demo job created. No real browser request.'});toast('Đã thêm retry mẫu vào session log.');render()}if(action==='scan-diff'){state.logs.unshift({t:time(),v:'Incremental scan demo: checking changed listing fingerprints.'});toast('Đã kích hoạt kiểm tra thay đổi trong mô phỏng.');render()}if(action==='scan-stop'){clearInterval(state.scanTimer);state.scanState='idle';state.logs.unshift({t:time(),v:'Stopped demo scan. Checkpoint retained.'});render()}if(action==='grid-view')toast('Grid đang được bật. List view là chức năng của bản triển khai thật.');if(action==='flag-product')toast('Đã đánh dấu bằng chứng nghi ngờ trong phiên demo.');if(action==='approve-profile'){state.approval=true;render();toast('Đã đánh dấu v0.3 là Approved trong prototype (không thay đổi CAM).')}if(action==='apply-profile')toast('Bản thật sẽ yêu cầu chọn workflow, profile version và kiểm tra quyền Apply.');if(action==='explain-method')toast('Phương pháp: quan sát → tần suất → confidence → evidence → exceptions → constraints.');});
document.addEventListener('change',e=>{if(e.target.id==='platform-filter'){state.platform=e.target.value;render()}if(['scan-shop','product-shop','dna-shop'].includes(e.target.id)){state.shop=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='shop-search'){const pos=e.target.selectionStart;state.search=e.target.value;render();const input=document.getElementById('shop-search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='product-search'){const pos=e.target.selectionStart;state.productSearch=e.target.value;render();const input=document.getElementById('product-search');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal)closeModal()});document.getElementById('notif').onclick=()=>toast('Không có thông báo thật trong prototype.');render();

